        throw new IllegalArgumentException("end index out of bounds: " + end);
    }

    int i = end;
    while (i >= 0) {
        char c = headerPart.charAt(i);
        if (c == '\n') {
            // Check if preceded by \r
            if (i > 0 && headerPart.charAt(i - 1) == '\r') {
                return i - 1;
            } else {
                return i;
            }
        }
        i--;
