        throw new NullPointerException("file must not be null");
    }
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files != null) {
            for (File child : files) {
                forceDeleteOnExit(child);
            }
        }
    }
    if (!file.delete()) {
        file.deleteOnExit();
        if (!file.exists()) {
            return;
        }
        throw new IOException("Failed to delete " + file);
    }
