protected void subAppend(LoggingEvent event) {
    try {
        // Get the message from the logging event
        String message = event.getRenderedMessage();

        // Get the level of the logging event
        String level = event.getLevel().toString();

        // Get the timestamp
        long timestamp = event.getTimeStamp();

        // Get the thread name
        String threadName = event.getThreadName();

        // Get the logger name
        String loggerName = event.getLoggerName();

        // Format the log message
        String formattedMessage = String.format("[%s] [%s] [%s] [%s] %s", 
                new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS").format(new java.util.Date(timestamp)),
                level,
                threadName,
                loggerName,
                message);

        // Write the formatted message to the output
        if (out != null) {
            out.write(formattedMessage + System.lineSeparator());
            out.flush();
        }
    } catch (Exception e) {
        // Handle any exceptions that occur during writing
        if (event.getThrowableStrRep() != null) {
            for (String line : event.getThrowableStrRep()) {
                try {
                    if (out != null) {
                        out.write(line + System.lineSeparator());
                    }
                } catch (Exception ex) {
                    // Ignore exceptions when writing stack trace
                }
            }
        }
    }
}
