public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] typeArguments = parameterizedType.getActualTypeArguments();
    if (typeArguments.length == 0) {
        return null;
    }
    Class<?>[] result = new Class<?>[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        Type typeArg = typeArguments[i];
        if (typeArg instanceof Class) {
            result[i] = (Class<?>) typeArg;
        } else if (typeArg instanceof ParameterizedType) {
            ParameterizedType paramType = (ParameterizedType) typeArg;
            Type rawType = paramType.getRawType();
            if (rawType instanceof Class) {
                result[i] = (Class<?>) rawType;
            } else {
                result[i] = null;
            }
        } else if (typeArg instanceof WildcardType) {
            WildcardType wildcardType = (WildcardType) typeArg;
            Type[] upperBounds = wildcardType.getUpperBounds();
            if (upperBounds.length > 0 && upperBounds[0] instanceof Class) {
                result[i] = (Class<?>) upperBounds[0];
            } else {
                result[i] = null;
            }
        } else if (typeArg instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) typeArg;
            String name = typeVariable.getName();
            Type[] bounds = typeVariable.getBounds();
            if (bounds.length > 0 && bounds[0] instanceof Class) {
                result[i] = (Class<?>) bounds[0];
            } else {
                result[i] = null;
            }
        } else {
            result[i] = null;
        }
    }
    for (Class<?> c : result) {
        if (c == null) {
            return null;
        }
    }
    return result;
}
