public Mappings diffStructure(String tableName, Mappings mappings) {
    if (tableName == null || tableName.isEmpty()) {
        throw new IllegalArgumentException("tableName must not be null or empty");
    }
    if (mappings == null) {
        throw new IllegalArgumentException("mappings must not be null");
    }

    Mappings result = new Mappings();
    Map<String, Object> properties = mappings.getProperties();
    if (properties != null && !properties.isEmpty()) {
        Map<String, Object> filteredProperties = new HashMap<>();
        for (Map.Entry<String, Object> entry : properties.entrySet()) {
            String fieldName = entry.getKey();
            if (fieldName == null || fieldName.isEmpty()) {
                continue;
            }
            // Skip _source field to avoid current index update conflict
            if ("_source".equals(fieldName)) {
                continue;
            }
            filteredProperties.put(fieldName, entry.getValue());
        }
        if (!filteredProperties.isEmpty()) {
            result.setProperties(filteredProperties);
        }
    }

    // Copy other mapping fields if they exist
    if (mappings.getDynamic() != null) {
        result.setDynamic(mappings.getDynamic());
    }
    if (mappings.getDynamicTemplates() != null) {
        result.setDynamicTemplates(mappings.getDynamicTemplates());
    }
    if (mappings.getMeta() != null) {
        result.setMeta(mappings.getMeta());
    }

    return result;
}
