    if (!adjacencyMap.containsKey(sourceVertex)) {
        adjacencyMap.put(sourceVertex, new ArrayList<>());
    }
    adjacencyMap.get(sourceVertex).add(e);

    // If the graph is undirected, also add the edge to the adjacency list of the target vertex
    if (!isDirected) {
        if (!adjacencyMap.containsKey(targetVertex)) {
