public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }
    double x1 = box.getX1();
    double x2 = box.getX2();
    double y1 = box.getY1();
    double y2 = box.getY2();

    if (x1 >= x2) {
        throw new IllegalArgumentException("Invalid box: x1 must be less than x2");
    }

    double midX = (x1 + x2) / 2.0;

    Box2D leftBox = new Box2D(x1, y1, midX, y2);
    Box2D rightBox = new Box2D(midX, y1, x2, y2);

    return new Pair<>(leftBox, rightBox);
}
