public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2;
    }
}

private static boolean isPrime(int n) {
    if (n < 2) {
        return false;
    }
    if (n == 2) {
        return true;
    }
    if (n % 2 == 0) {
        return false;
    }
    for (int i = 3; i * i <= n; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}
