    private Map<String, Object> buildContent(JsonObject jsonObject) {
        Map<String, Object> content = new HashMap<>();
        if (jsonObject == null) {
            return content;
        }
        for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
            String key = entry.getKey();
            JsonElement value = entry.getValue();
            if (value.isJsonNull()) {
                content.put(key, null);
            } else if (value.isJsonPrimitive()) {
                JsonPrimitive primitive = value.getAsJsonPrimitive();
                if (primitive.isString()) {
                    content.put(key, primitive.getAsString());
                } else if (primitive.isNumber()) {
                    content.put(key, primitive.getAsNumber());
                } else if (primitive.isBoolean()) {
                    content.put(key, primitive.getAsBoolean());
                }
            } else if (value.isJsonObject()) {
                content.put(key, buildContent(value.getAsJsonObject()));
            } else if (value.isJsonArray()) {
                List<Object> list = new ArrayList<>();
                for (JsonElement element : value.getAsJsonArray()) {
                    if (element.isJsonNull()) {
                        list.add(null);
                    } else if (element.isJsonPrimitive()) {
                        JsonPrimitive primitive = element.getAsJsonPrimitive();
                        if (primitive.isString()) {
                            list.add(primitive.getAsString());
                        } else if (primitive.isNumber()) {
                            list.add(primitive.getAsNumber());
                        } else if (primitive.isBoolean()) {
                            list.add(primitive.getAsBoolean());
                        }
                    } else if (element.isJsonObject()) {
                        list.add(buildContent(element.getAsJsonObject()));
                    } else if (element.isJsonArray()) {
                        list.add(buildContent(element.getAsJsonObject()));
                    }
                }
                content.put(key, list);
            }
        }
        return content;
    }
