```java
public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    int len = str.length();
    if (len == 0) {
        return str;
    }
    StringBuilder buf = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                buf.append(c);
                continue;
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case '0':
                    buf.append('\0');
                    i++;
                    break;
                case 't':
                    buf.append('\t');
                    i++;
                    break;
                case 'b':
                    buf.append('\b');
                    i++;
                    break;
                case 'n':
                    buf.append('\n');
                    i++;
                    break;
                case 'r':
                    buf.append('\r');
                    i++;
                    break;
                case 'f':
                    buf.append('\f');
                    i++;
                    break;
                case 'a':
                    buf.append('\u0007');
                    i++;
                    break;
                case 'v':
                    buf.append('\u000B');
                    i++;
                    break;
                case 'e':
                    buf.append('\u001B');
                    i++;
                    break;
                case 's':
                    buf.append(' ');
                    i++;
                    break;
                case '\'':
                    buf.append('\'');
                    i++;
                    break;
                case '"':
                    buf.append('"');
                    i++;
                    break;
                case '\\':
                    buf.append('\\');
                    i++;
                    break;
                case 'u':
                    if (i + 5 < len) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int codePoint = Integer.parseInt(hex, 16);
                            buf.append((char) codePoint);
                            i += 5;
                        } catch (NumberFormatException e) {
                            buf.append(c);
                        }
                    } else {
                        buf.append(c);
                    }
                    break;
                default:
                    buf.append(c);
                    break;
            }
        } else {
            buf.append(c);
        }
    }
    return buf.toString();
}
