final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    try {
        int offset = constantPoolEntryIndex;
        // Read the tag (should be CONSTANT_Utf8 = 1)
        int tag = classFileBuffer.get(offset);
        if (tag != 1) {
            throw new IllegalArgumentException("Not a CONSTANT_Utf8 entry at index " + constantPoolEntryIndex);
        }
        offset += 1; // skip tag

        // Read the length (2 bytes, unsigned short)
        int length = ((classFileBuffer.get(offset) & 0xFF) << 8) | (classFileBuffer.get(offset + 1) & 0xFF);
        offset += 2;

        // Read the bytes and decode as UTF-8
        byte[] bytes = new byte[length];
        for (int i = 0; i < length; i++) {
            bytes[i] = classFileBuffer.get(offset + i);
        }

        // Decode UTF-8 bytes to chars
        int charCount = 0;
        int i = 0;
        while (i < length) {
            int b = bytes[i] & 0xFF;
            if (b < 0x80) {
                charBuffer[charCount++] = (char) b;
                i += 1;
            } else if (b < 0xE0) {
                if (i + 1 >= length) {
                    throw new IllegalArgumentException("Invalid UTF-8 sequence");
                }
                int b2 = bytes[i + 1] & 0xFF;
                if ((b2 & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Invalid UTF-8 sequence");
                }
                charBuffer[charCount++] = (char) (((b & 0x1F) << 6) | (b2 & 0x3F));
                i += 2;
            } else if (b < 0xF0) {
                if (i + 2 >= length) {
                    throw new IllegalArgumentException("Invalid UTF-8 sequence");
                }
                int b2 = bytes[i + 1] & 0xFF;
                int b3 = bytes[i + 2] & 0xFF;
                if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Invalid UTF-8 sequence");
                }
                charBuffer[charCount++] = (char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F));
                i += 3;
            } else {
                if (i + 3 >= length) {
                    throw new IllegalArgumentException("Invalid UTF-8 sequence");
                }
                int b2 = bytes[i + 1] & 0xFF;
                int b3 = bytes[i + 2] & 0xFF;
                int b4 = bytes[i + 3] & 0xFF;
                if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80 || (b4 & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Invalid UTF-8 sequence");
                }
                int codePoint = ((b & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F);
                if (codePoint >= 0x10000) {
                    codePoint -= 0x10000;
                    charBuffer[charCount++] = (char) (0xD800 + (codePoint >> 10));
                    charBuffer[charCount++] = (char) (0xDC00 + (codePoint & 0x3FF));
                } else {
                    charBuffer[charCount++] = (char) codePoint;
                }
                i += 4;
            }
        }

        return new String(charBuffer, 0, charCount);
    } catch (Exception e) {
        throw new RuntimeException("Error reading UTF-8 constant pool entry", e);
    }
