public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (nameStart < 0 || nameStart >= name.length()) {
        return;
    }
    // Find the end of the name (next space or end of string)
    int nameEnd = nameStart;
    while (nameEnd < name.length() && name.charAt(nameEnd) != ' ') {
        nameEnd++;
    }
    // Get the name
    String name = this.name.substring(nameStart, nameEnd);
    if (name.isEmpty()) {
        return;
    }
    // Abbreviate: first letter + last letter if length > 2, else first letter
    if (name.length() == 1) {
        buf.append(name.charAt(0));
    } else if (name.length() == 2) {
        buf.append(name.charAt(0));
        buf.append(name.charAt(1));
    } else {
        buf.append(name.charAt(0));
        buf.append(name.charAt(name.length() - 1));
    }
}
