    private void pop(final String descriptor) {
        if (descriptor == null) {
            throw new IllegalArgumentException("Descriptor must not be null");
        }
        int i = 0;
        int len = descriptor.length();
        while (i < len) {
            char c = descriptor.charAt(i);
            if (c == '(') {
                // Method descriptor: skip the '(' and process arguments until ')'
                i++;
                while (i < len && descriptor.charAt(i) != ')') {
                    popType(descriptor, i);
                    i = skipType(descriptor, i);
                }
                if (i < len && descriptor.charAt(i) == ')') {
                    i++;
                }
                // After ')', there is a return type, but we don't pop it
                // We are done with the method descriptor
                break;
            } else {
                // Single type descriptor
                popType(descriptor, i);
                i = skipType(descriptor, i);
            }
        }
    }

    private void popType(final String descriptor, final int index) {
        char c = descriptor.charAt(index);
        switch (c) {
            case 'B': // boolean
            case 'C': // char
            case 'D': // double
            case 'F': // float
            case 'I': // int
            case 'J': // long
            case 'S': // short
            case 'Z': // boolean
                outputFrame.pop();
                break;
            case 'L': // object type
                outputFrame.pop();
                break;
            case '[': // array
                outputFrame.pop();
                break;
            default:
                throw new IllegalArgumentException("Invalid type descriptor character: " + c);
        }
    }

    private int skipType(final String descriptor, final int index) {
        char c = descriptor.charAt(index);
        switch (c) {
            case 'B':
            case 'C':
            case 'D':
            case 'F':
            case 'I':
            case 'J':
            case 'S':
            case 'Z':
                return index + 1;
            case 'L':
                // Find the closing ';'
                int end = descriptor.indexOf(';', index);
                if (end == -1) {
                    throw new IllegalArgumentException("Invalid type descriptor: missing ';'");
                }
                return end + 1;
            case '[':
                // Array type: skip the '[' and then skip the component type
                return skipType(descriptor, index + 1);
            default:
                throw new IllegalArgumentException("Invalid type descriptor character: " + c);
        }
    }
