public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path must not be null");
    }

    // Normalize the base path: ensure it ends with a separator if it's a directory
    // But we need to handle the case where path might be a file path
    // The relative path is applied relative to the directory containing the path

    // First, let's normalize both paths
    String normalizedPath = path.replace("\\", "/");
    String normalizedRelative = relativePath.replace("\\", "/");

    // If the relative path is empty, return the normalized path
    if (normalizedRelative.isEmpty()) {
        return normalizedPath;
    }

    // If the relative path starts with "/", it's actually an absolute path
    if (normalizedRelative.startsWith("/")) {
        return normalizedRelative;
    }

    // We need to find the directory part of the base path
    // If the base path ends with "/", it's a directory
    // Otherwise, we need to strip the last component to get the directory

    String basePath = normalizedPath;
    if (basePath.endsWith("/")) {
        // It's a directory, use as is
    } else {
        // Find the last separator
        int lastSep = basePath.lastIndexOf('/');
        if (lastSep == -1) {
            // No separator, so the base is just a filename, directory is ""
            basePath = "";
        } else {
            basePath = basePath.substring(0, lastSep + 1);
        }
    }

    // Now combine basePath with relativePath
    String combined = basePath + normalizedRelative;

    // Normalize the combined path: resolve "." and ".."
    String[] parts = combined.split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
            // If stack is empty, we can't go up, so ignore
        } else {
            stack.push(part);
        }
    }

    // Build the result
    StringBuilder result = new StringBuilder();
    // Check if the original path was absolute
    boolean isAbsolute = normalizedPath.startsWith("/");
    if (isAbsolute) {
        result.append("/");
    }

    // The stack is in reverse order, so we need to reverse it
    java.util.List<String> reversed = new java.util.ArrayList<>();
    while (!stack.isEmpty()) {
        reversed.add(stack.pop());
    }

    for (int i = 0; i < reversed.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(reversed.get(i));
    }

    // If the result is empty and it was absolute, return "/"
    if (result.length() == 0) {
        if (isAbsolute) {
            return "/";
        } else {
            return "";
        }
    }

    return result.toString();
}
