        if (obj != null) {
            count++;
        }
    }
    if (count == array.length) {
        // Check if all elements are Strings
        boolean allStrings = true;
        for (Object obj : array) {
            if (!(obj instanceof String)) {
                allStrings = false;
                break;
            }
        }
        if (allStrings) {
            return (String[]) array;
        }
    }
    String[] result = new String[count];
    int index = 0;
    for (Object obj : array) {
        if (obj != null) {
            result[index++] = obj.toString();
        }
    }
    return result;
